function range(start, end) {
  let current = start;
  return {
    next() {
      if (current > end) return { done: true };
      return { value: current++, done: false };
    },
    [Symbol.iterator]() { return this; },
  };
}

for (const n of range(1, 3)) console.log(n); // 1 2 3
console.log([...range(1, 3)]);

